const D = { scale:1, density:.6, energy:.6, glow:.7, hue:210, chrome:.8, speed:1, x:.5, y:.94, style:'chrome', act:'diner', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = Math.PI*2;
const u = Math.min(width,height);
const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
const hw = h => ((h%360)+360)%360;
const clamp = (v,a,b) => v<a?a:(v>b?b:v);

// ---- geometry ----
const scl = P.scale;
const jw = u*0.46*scl, jh = u*0.80*scl;
const cx = P.x*width, by = P.y*height;
const top = by - jh, left = cx - jw/2, right = cx + jw/2;
const inset = jw*0.11;
const lx = left+inset, rx = right-inset;
const tubeBotY = by - jh*0.09;
const ay = top + jh*0.30;            // where verticals meet the arch
const rArc = (rx-lx)/2;
const LvA = Math.max(1, tubeBotY-ay);
const totalA = LvA + (Math.PI/2)*rArc;
// rising path, left stream: s 0(bottom)->1(top center)
const pathA = s => {
  const d = s*totalA;
  if (d < LvA) return [lx, tubeBotY-d];
  const a = Math.PI - (d-LvA)/rArc;   // PI -> PI/2
  return [cx + rArc*Math.cos(a), ay - rArc*Math.sin(a)];
};

// ---- style ----
const STY = {
  chrome:    { mode:'solid', metal:[208,10,88], metalD:[210,16,44], panel:[hw(P.hue),46,20], grille:[34,26,32], win:[46,70,96], wire:false, halftone:false, neon:false, gloss:true },
  neon:      { mode:'neon',  metal:[hw(P.hue),55,66], metalD:[hw(P.hue),75,26], panel:[hw(P.hue),85,10], grille:[hw(P.hue),50,22], win:[48,90,96], wire:false, halftone:false, neon:true, gloss:false },
  riso:      { mode:'riso',  metal:[6,68,92], metalD:[6,68,92], panel:[202,66,84], grille:[6,58,86], win:[46,74,92], wire:false, halftone:true, neon:false, gloss:false },
  blueprint: { mode:'wire',  metal:[194,64,74], metalD:[210,72,18], panel:[212,72,14], grille:[196,46,52], win:[192,60,60], wire:true, halftone:false, neon:false, gloss:false },
  noir:      { mode:'solid', metal:[220,6,74], metalD:[220,10,16], panel:[222,10,10], grille:[220,7,26], win:[42,16,86], wire:false, halftone:false, neon:false, gloss:true }
};
const sty = STY[P.style] || STY.chrome;

// ---- cached cabinet buffer ----
const key = width+'x'+height+':'+scl.toFixed(3)+':'+Math.round(P.hue)+':'+P.style+':'+P.seed;
if (!S.gfx || S.key !== key) {
  const g = S.gfx || (S.gfx = createGraphics(width, height));
  g.colorMode(HSB,360,100,100,100);
  g.clear();
  g.push();
  // cabinet silhouette: rounded-shoulder arch
  const shoulderY = top + jh*0.34;
  const shape = (ctx) => {
    ctx.beginShape();
    ctx.vertex(left, by);
    ctx.vertex(left, shoulderY);
    ctx.bezierVertex(left, top+jh*0.04, cx-jw*0.30, top, cx, top);
    ctx.bezierVertex(cx+jw*0.30, top, right, top+jh*0.04, right, shoulderY);
    ctx.vertex(right, by);
    ctx.endShape(CLOSE);
  };
  if (sty.wire) {
    g.noFill(); g.stroke(sty.panel[0],sty.panel[1],40); g.strokeWeight(Math.max(1,u*0.004)); g.rectMode(CORNER);
    // dark schematic panel behind
    g.fill(sty.panel[0],sty.panel[1],sty.panel[2]); g.noStroke();
    g.rect(left-inset*0.4, top-jh*0.02, jw+inset*0.8, jh+jh*0.02, u*0.02);
    g.noFill(); g.stroke(sty.metal[0],sty.metal[1],sty.metal[2]); g.strokeWeight(Math.max(1.2,u*0.0045));
    shape(g);
    // schematic grille + crosshatch
    for (let i=0;i<9;i++){ const yy = top+jh*0.50 + i*(jh*0.045); g.line(left+inset*0.5, yy, right-inset*0.5, yy); }
    for (let i=0;i<6;i++){ const xx = left+inset*0.6 + i*((jw-inset*1.2)/5); g.line(xx, top+jh*0.48, xx, top+jh*0.86); }
    g.stroke(sty.win[0],sty.win[1],sty.win[2]); g.rect(cx-jw*0.28, top+jh*0.18, jw*0.56, jh*0.20, u*0.01);
    // dimension ticks
    g.strokeWeight(1); g.stroke(sty.metal[0],40,60);
    for (let i=0;i<12;i++){ const s=i/11; const p=pathA(s); g.point(p[0],p[1]); g.point(2*cx-p[0],p[1]); }
  } else {
    // solid body panel + metal frame overlay
    g.noStroke(); g.fill(sty.panel[0],sty.panel[1],sty.panel[2]);
    shape(g);
    // vertical wood/metal grain
    if (sty.halftone) {
      g.fill(sty.grille[0],sty.grille[1],sty.grille[2]);
      for (let yy=top; yy<by; yy+=Math.max(3,u*0.012)){
        for (let xx=left; xx<right; xx+=Math.max(3,u*0.012)){
          const dd = (xx-cx); if (Math.abs(dd) > jw*0.5) continue;
          const rr = Math.max(0.6, u*0.004*(0.4+fr(xx*3.1+yy)*0.9));
          if (yy>top+jh*0.34 || Math.abs(dd)<jw*0.30) g.circle(xx,yy,rr);
        }
      }
    }
    // chrome shoulder frame
    const fw = Math.max(2,u*0.02);
    g.noFill(); g.strokeWeight(fw);
    g.stroke(sty.metalD[0],sty.metalD[1],sty.metalD[2]); shape(g);
    g.strokeWeight(fw*0.5); g.stroke(sty.metal[0],sty.metal[1],sty.metal[2]); shape(g);
    // central lit title window
    g.noStroke(); g.fill(sty.win[0],sty.win[1],sty.win[2]*0.9);
    g.rect(cx-jw*0.30, top+jh*0.16, jw*0.60, jh*0.19, u*0.012);
    g.fill(0,0,10,40); g.rect(cx-jw*0.28, top+jh*0.185, jw*0.56, jh*0.14, u*0.008);
    // title text ribs
    g.stroke(sty.metalD[0],sty.metalD[1],sty.metalD[2],60); g.strokeWeight(Math.max(1,u*0.003));
    for (let i=0;i<4;i++){ const yy=top+jh*0.205+i*(jh*0.032); g.line(cx-jw*0.24,yy,cx+jw*0.24,yy); }
    // speaker grille (chevron / horizontal)
    g.noStroke();
    for (let i=0;i<11;i++){
      const yy = top+jh*0.52 + i*(jh*0.032);
      const b = sty.grille[2]*(0.55+0.4*(i%2));
      g.fill(sty.grille[0],sty.grille[1],b);
      g.rect(cx-jw*0.34, yy, jw*0.68, jh*0.018, u*0.006);
    }
    // base plinth
    g.fill(sty.metalD[0],sty.metalD[1],sty.metalD[2]);
    g.rect(left-inset*0.3, by-jh*0.06, jw+inset*0.6, jh*0.06, u*0.006);
    g.fill(sty.metal[0],sty.metal[1],sty.metal[2]*0.9);
    g.rect(left-inset*0.3, by-jh*0.06, jw+inset*0.6, jh*0.012);
    // glass tube channels (dark grooves the bubbles ride in)
    g.noFill(); g.strokeWeight(Math.max(3,u*0.02));
    g.stroke(sty.panel[0],sty.panel[1],Math.max(4,sty.panel[2]*0.4));
    g.beginShape();
    for (let i=0;i<=24;i++){ const p=pathA(i/24); g.vertex(p[0],p[1]); }
    g.endShape();
    g.beginShape();
    for (let i=0;i<=24;i++){ const p=pathA(i/24); g.vertex(2*cx-p[0],p[1]); }
    g.endShape();
    if (sty.gloss){
      g.strokeWeight(Math.max(1,u*0.006)); g.stroke(0,0,100,26);
      g.beginShape(); for (let i=0;i<=24;i++){ const p=pathA(i/24); g.vertex(p[0]-u*0.006,p[1]); } g.endShape();
      g.beginShape(); for (let i=0;i<=24;i++){ const p=pathA(i/24); g.vertex(2*cx-p[0]-u*0.006,p[1]); } g.endShape();
    }
  }
  g.pop();
  S.key = key;
}

// ---- draw cached cabinet ----
image(S.gfx, 0, 0);

// ---- act dramaturgy ----
let cycleRate = 6, bubbleMul = 1, glowMul = 1;
if (P.act === 'rave') { cycleRate = 1.6; bubbleMul = 1.5; glowMul = 1.3; }
else if (P.act === 'lonely') { cycleRate = 22; bubbleMul = 0.5; glowMul = 0.65; }

// tube hue cycles per section + slow real-time drift (never re-phases)
const secShift = K.section*44;
const tubeH = hw(P.hue + 120 + secShift + K.t*(360/Math.max(2,cycleRate*10)) );
const glow = P.glow*glowMul*(0.55 + 0.45*K.swell) + A.bass*0.5;
const kick = K.pulse*0.7 + A.bass*0.7;

// ---- rising bubbles (continuous K.t motion floor) ----
const NB = Math.round(6 + P.density*bubbleMul*40);
push();
blendMode(ADD);
for (let i=0;i<NB;i++){
  const stream = fr(i*1.7) < 0.5 ? 0 : 1;
  const off = fr(i*2.3);
  const sp = 0.10 + fr(i*3.7)*0.16;
  let s = (off + K.t*sp*P.speed*0.9) % 1;
  const p = pathA(s);
  const x = stream ? 2*cx - p[0] : p[0];
  const yv = p[1];
  const wob = Math.sin(K.t*2.2 + i*1.3)*u*0.004;
  const bh = hw(tubeH + (fr(i*5.1)-0.5)*30);
  const grow = 1 + kick*0.5*Math.exp(-Math.abs(s-K.cyc)*4);
  const r = (u*0.006 + fr(i*4.4)*u*0.010) * (0.7+s*0.6) * grow * (0.9+P.energy*0.4);
  const al = clamp((14 + glow*22) * (0.5+0.6*Math.sin(s*Math.PI)), 0, 60);
  fill(bh, 62, 96, al);
  circle(x+wob, yv, r*2);
  fill(bh, 20, 100, al*0.7);
  circle(x+wob - r*0.3, yv - r*0.3, r*0.7);
}
blendMode(BLEND);
pop();

// ---- title window glow flicker + neon arch ----
push();
blendMode(ADD);
const winGlow = clamp((10 + glow*30)*(0.7+0.3*Math.sin(K.t*3.1)), 0, 60);
noStroke(); fill(hw(P.hue+40), 30, 100, winGlow*0.5);
rect(cx-jw*0.30, top+jh*0.16, jw*0.60, jh*0.19, u*0.012);
// neon arch outline pulse (all styles get a subtle rim; neon style stronger)
const neonAmp = sty.neon ? 1 : 0.4;
drawingContext.shadowBlur = (10 + glow*26)*neonAmp;
drawingContext.shadowColor = 'hsla('+Math.round(tubeH)+',90%,60%,0.9)';
noFill(); strokeWeight(Math.max(1.5,u*0.006)*neonAmp);
stroke(tubeH, 70, 100, 40+kick*40);
beginShape();
for (let i=0;i<=24;i++){ const p=pathA(i/24); vertex(p[0],p[1]); }
endShape();
beginShape();
for (let i=0;i<=24;i++){ const p=pathA(i/24); vertex(2*cx-p[0],p[1]); }
endShape();
drawingContext.shadowBlur = 0;
blendMode(BLEND);
pop();

// ---- chrome glint sweeping across the dome (real-time) ----
if (!sty.wire) {
  push();
  const gx = left + (0.5+0.5*Math.sin(K.t*0.6))*jw;
  const chr = P.chrome;
  blendMode(SCREEN);
  noStroke();
  for (let i=0;i<4;i++){
    const a = (10+chr*16) * (1 - i/4);
    fill(0,0,100,a);
    ellipse(gx, top+jh*0.30, u*0.012*(1+i*1.2), jh*0.5);
  }
  // beat spark on the title
  fill(0,0,100, kick*30*chr);
  ellipse(cx - jw*0.18 + Math.sin(K.t*4)*jw*0.1, top+jh*0.255, u*0.05, u*0.02);
  blendMode(BLEND);
  pop();
}
